"""Deterministic build order for a dependency graph. See task.md."""

from __future__ import annotations

import heapq
from collections import deque


class CycleError(ValueError):
    """Raised when the graph contains a cycle.

    `.cycle` names the members of the reported cycle, in depends-on order,
    without repeating the first member at the end.
    """

    def __init__(self, cycle: list[str]) -> None:
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = list(cycle)


def resolve(graph: dict[str, list[str]]) -> list[str]:
    """Return the build order of `graph`, dependencies first."""
    deps: dict[str, set[str]] = {}
    for node, ds in graph.items():
        deps.setdefault(node, set()).update(ds)
        for d in ds:
            deps.setdefault(d, set())

    dependents: dict[str, list[str]] = {n: [] for n in deps}
    remaining = {n: len(ds) for n, ds in deps.items()}
    for n, ds in deps.items():
        for d in ds:
            dependents[d].append(n)

    heap = [n for n, c in remaining.items() if c == 0]
    heapq.heapify(heap)
    order: list[str] = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in dependents[n]:
            remaining[m] -= 1
            if remaining[m] == 0:
                heapq.heappush(heap, m)

    if len(order) == len(deps):
        return order
    raise CycleError(_find_cycle({n: sorted(deps[n]) for n in deps if remaining[n] > 0}))


def _find_cycle(adj: dict[str, list[str]]) -> list[str]:
    """Shortest cycle, ties broken by smallest rotation-normalised list."""
    nodes = sorted(adj)
    radj: dict[str, list[str]] = {n: [] for n in nodes}
    for n in nodes:
        for d in adj[n]:
            if d in radj:
                radj[d].append(n)

    best: tuple[int, list[str]] | None = None
    for s in nodes:
        dist = {s: 0}
        queue = deque([s])
        while queue:
            x = queue.popleft()
            for y in radj[x]:
                if y >= s and y not in dist:
                    dist[y] = dist[x] + 1
                    queue.append(y)
        length = min((dist[v] for v in adj[s] if v in dist), default=None)
        if length is None:
            continue
        length += 1
        if best is not None and length > best[0]:
            continue
        path = [s]
        cur = s
        for i in range(1, length):
            cur = min(v for v in adj[cur] if v > s and dist.get(v) == length - i)
            path.append(cur)
        if best is None or (length, path) < best:
            best = (length, path)
    assert best is not None
    return best[1]
